const std = @import("std");
// This parser is generated by pgen.zig during build process.
const parser_mod = @import("parser");

pub fn main(init: std.process.Init) !u8 {
    const io = init.io;
    // This is appropriate for anything that lives as long as the process.
    const arena: std.mem.Allocator = init.arena.allocator();

    var arg_it = try init.minimal.args.iterateAllocator(arena);
    defer arg_it.deinit();
    std.debug.assert(arg_it.skip());
    const expression_src = arg_it.next() orelse {
        std.debug.print("expected one argument (the math expression to compute)\n", .{});
        return 1;
    };
    _ = expression_src;

    var parser = try parser_mod.Parser.init(arena);
    defer parser.deinit(arena);

    var stdout_buffer: [1024]u8 = undefined;
    var stdout_file_writer: std.Io.File.Writer = .init(.stdout(), io, &stdout_buffer);
    const stdout_writer = &stdout_file_writer.interface;

    try stdout_writer.writeAll(
        \\The parser initializes successfully!
        \\This demo is intended to demo the build integration (see build.zig).
        \\Actual calculation capability will be added soon.
        \\
    );

    try stdout_writer.flush();
    return 0;
}
